#!/usr/bin/env python3
import sys, os, re, json, base64, subprocess, shutil, shlex

VERSION = "1.23.0"

def bash_quote(s):
    if s == "":
        return "''"
    safe_punct = set("!+,-./:@]^_{}")
    for ch in s:
        if ch.isalnum() or ch in safe_punct:
            continue
        else:
            return "'" + s.replace("'", "'\\''") + "'"
    return s

def bash_quote_array(arr):
    if not arr:
        return "(  )"
    return "( " + " ".join(bash_quote(x) for x in arr) + " )"

def run_choice_fn(script_path, fn_name):
    try:
        qpath = shlex.quote(script_path)
        cmd = ["bash", "-c", f'source {qpath} > /dev/null 2>&1; {fn_name}']
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            return []
        lines = [l for l in r.stdout.splitlines() if l != ""]
        return lines
    except Exception:
        return []

PYEOF
cat argc.py
