# ---------- parsing helpers ----------
def split_tag_content(s):
    # Split tag content into tokens, respecting that describe may contain spaces.
    # We just split by whitespace for param parsing; describe is rest.
    # But need to handle backticks with spaces? Unlikely. Notations don't have spaces inside.
    # So simple split is fine.
    return s.strip().split()

def parse_choice_default(s):
    # s is like "[a|b]", "[=a|b]", "[`_fn`]", "[?`_fn`]", "[a|b]", etc.
    # Returns (choice, default) where choice is {"type":...} or None, default is {...} or None
    # Also handles "=value" vs "[...]"?
    # For now, handle bracket content.
    if not s.startswith("[") or not s.endswith("]"):
        return None, None
    inner = s[1:-1]
    # Check for "?`fn`" (no validation) or "`fn`" (with validation)
    if inner.startswith("?`") and inner.endswith("`"):
        fn = inner[2:-1]
        return {"type": "Fn", "data": [fn, False]}, None
    if inner.startswith("`") and inner.endswith("`"):
        fn = inner[1:-1]
        return {"type": "Fn", "data": [fn, True]}, None
    if inner.startswith("="):
        # "[=a|b]" -> choice + default where default is first value?
        rest = inner[1:]
        parts = rest.split("|")
        # default is first part? For "[=a|b]", parts ["a","b"], default "a", choice ["a","b"]
        # For "[=x|y|z]" similar.
        # What about "[=a]" single? Then choice ["a"], default "a"?
        # Check export for "[=a|b]": choice ["a","b"], default "a". Yes.
        vals = [p for p in parts if p != ""]
        if not vals:
            return None, None
        default_val = vals[0]
        return {"type": "Values", "data": vals}, {"type": "Value", "value": default_val}
    else:
        # "[a|b]" -> choice, no default
        # Could also be "[a]"? Single choice?
        # Could be empty? Unlikely.
        # Check if inner contains "|": split, else single?
        if "|" in inner:
            vals = inner.split("|")
            return {"type": "Values", "data": vals}, None
        elif inner == "":
            return None, None
        else:
            # Single value? e.g., "[a]"? Treat as choice with single?
            # Or could be "[`_fn`]" already handled. So this is single choice value?
            return {"type": "Values", "data": [inner]}, None

def parse_default_value(s):
    # s is like "=a", "=`_fn`", "=val", etc. (starting with "=")
    # Returns default dict
    if not s.startswith("="):
        return None
    val = s[1:]
    if val.startswith("`") and val.endswith("`"):
        fn = val[1:-1]
        return {"type": "Fn", "value": fn}
    else:
        return {"type": "Value", "value": val}

PYEOF
echo "appended helpers"
